// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * The head of a section: an optional badge, the heading (h1 or h2) with an optional link opposite it, and an
 * optional lead. No wrapper: its parts are children of the section stack.
 */
import { type JSX } from "solid-js";
import { Badge, Group, Link, Text, Title } from "../compose";
import { defaults } from "../presets/defaults";
import { cn, urlOf } from "../utils";
import type { SectionHeading, HeadLink } from "./section-frame.types";

export type SectionHeaderProps = {
  titleId: string;
  title?: string;
  heading?: SectionHeading;
  action?: HeadLink;
  lead?: string;
  center?: boolean;
};

export function SectionHeader({
  titleId,
  title = "",
  heading,
  action,
  lead,
  center = false,
}: SectionHeaderProps) {
  const level = heading?.level ?? 2;
  const scale = heading?.scale ?? "default";
  const hasAction = action?.label && action?.href;
  return (
    <>
      {heading?.badge ? (
        <Badge variant="outline" size="lg" class={(center ? "mx-auto w-fit" : "w-fit")} data-testid="section-badge">
          {heading?.badge}
        </Badge>
      ) : null}
      {(((title as string) !== "") && hasAction) ? (
        <Group gap="4" align="center" justify="between" class="w-full flex-wrap">
          <Title
            as={level}
            size={((level === 1) ? "5xl" : "xl")}
            weight="semibold"
            class={
              (scale as string) === "display" ? "text-6xl tracking-tight md:text-8xl"
              : level === 1 ? "leading-tight"
              : "leading-7"
            }
            id={titleId}
          >
            {title}
          </Title>
          <Link
            href={urlOf(action?.href)}
            variant="default"
            class={cn(defaults.text.tiny, "shrink-0 font-medium leading-5")}
            data-testid="section-action"
          >
            {action?.label}
          </Link>
        </Group>
      ) : null}
      {(((title as string) !== "") && !hasAction) ? (
        <Title
          as={level}
          size={((level === 1) ? "5xl" : "xl")}
          weight="semibold"
          class={
            (scale as string) === "display" ? "text-6xl tracking-tight md:text-8xl"
            : level === 1 ? "leading-tight"
            : "leading-7"
          }
          id={titleId}
        >
          {title}
        </Title>
      ) : null}
      {(((title as string) === "") && hasAction) ? (
        <Group gap="4" align="center" justify="end" class="w-full">
          <Link
            href={urlOf(action?.href)}
            variant="default"
            class={cn(defaults.text.tiny, "shrink-0 font-medium leading-5")}
            data-testid="section-action"
          >
            {action?.label}
          </Link>
        </Group>
      ) : null}
      {lead ? (
        <Text size="base" class={cn("max-w-2xl text-muted-foreground", (center ? "mx-auto" : ""))}>
          {lead}
        </Text>
      ) : null}
    </>
  );
}
